<?php
require_once 'config.php';require_login();$page_title='Customers';$customers=$pdo->query('SELECT c.*,COUNT(o.id) AS orders_count,COALESCE(SUM(o.total),0) AS spent FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY c.id DESC')->fetchAll();require 'partials/header.php';
?><div class="panel"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Email</th><th>Orders</th><th>Total spent</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['phone']?:'—')?></td><td><?=e($c['email']?:'—')?></td><td><?=(int)$c['orders_count']?></td><td>₹<?=number_format((float)$c['spent'],2)?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$customers):?><p class="empty">No customers recorded yet.</p><?php endif;?></div><?php require 'partials/footer.php';?>
